-- public.warder_skin_after(p_world uuid, p_by uuid, p_on uuid, p_size double precision)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.warder_skin_after(p_world uuid, p_by uuid, p_on uuid, p_size double precision)
 RETURNS double precision
 LANGUAGE sql
 STABLE
AS $function$
  select case when pk(p_world, p_by, 'skin:over', 0) > 0
              then least(t.was + p_size, pk(p_world, p_by, 'skin:over', 0) * greatest(t.was, p_size))
              else greatest(t.was, p_size) end
    from (select coalesce((pl.stats->>'aegis')::double precision, 0) as was
            from player pl where pl.world_id = p_world and pl.uid = p_on) t
$function$
